<?php
namespace App\Http\Controllers;
use App\Http\Requests\{PaymentActionRequest,StorePembayaranRequest}; use App\Models\{Pembayaran,Transaksi}; use App\Services\PaymentService; use Illuminate\Http\Request; use Throwable;
class PaymentController extends Controller { public function create(Request $r,Transaksi $transaksi){abort_unless(in_array($transaksi->jenis_transaksi,['servis','cuci_mobil','penjualan_sparepart','trade_in'],true),404);return view('payments.create',compact('transaksi'));} public function store(StorePembayaranRequest $r,Transaksi $transaksi,PaymentService $svc){try{app(\App\Services\GatewayPaymentGuard::class)->assertManualAllowed($transaksi);$proof=$r->file('bukti_transfer')?->store('pembayaran','public');$d=$r->validated();$svc->create($transaksi->id_transaksi,(int)($r->user()->petugas?->id_petugas ?? app(\App\Services\InventoryService::class)->actorPetugasId($r->user()->id_user)),(string)$d['jumlah'],$d['metode'],$proof,$d['catatan']??null);return back()->with('success','Pembayaran tersimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}} public function verify(PaymentActionRequest $r,Pembayaran $pembayaran,PaymentService $svc){try{$tx=$pembayaran->transaksi;app(\App\Services\GatewayPaymentGuard::class)->assertManualAllowed($tx);$svc->verify($pembayaran->id_pembayaran,(int)($r->user()->petugas?->id_petugas ?? app(\App\Services\InventoryService::class)->actorPetugasId($r->user()->id_user)));return back()->with('success','Pembayaran diverifikasi.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}} public function reject(PaymentActionRequest $r,Pembayaran $pembayaran,PaymentService $svc){try{$svc->reject($pembayaran->id_pembayaran,(int)($r->user()->petugas?->id_petugas ?? app(\App\Services\InventoryService::class)->actorPetugasId($r->user()->id_user)));return back()->with('success','Pembayaran ditolak.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}} }
